                 (unsigned long)g_sd_dead_tries,
                 (unsigned long long)((now - g_sd_dead_since_us) / 1000ull));
          nxmutex_unlock(&g_sd_lock);
          break;
        }

      if (g_sd_dead_mute < 0xffffu)
