          g_sd_dead_mute++;
        }

      syslog(LOG_WARNING, "SD: still dead after hard reset #%lu (n=%u)\n",
             (unsigned long)g_sd_dead_tries, (unsigned)g_sd_dead_mute);
      nxmutex_unlock(&g_sd_lock);

